function crtAtual(t){const d=Math.max(0,crtDias(t)-CRT_CFG.tolerancia>0?crtDias(t):0);if(!d)return {multa:0,juros:0,tot:t.valor,d:0};const multa=r2(t.valor*CRT_CFG.multa/100),juros=r2(t.valor*CRT_CFG.juros/100*d/30);return {multa,juros,tot:r2(t.valor+multa+juros),d}}
