function crtTermo(id){const a=CRT_ACORDOS.find(x=>x.id===id);openModal(`${mh('Termo de acordo · '+id)}<div class="mb"><div class="laudo" style="max-width:none"><div class="lh"><b>Termo de acordo de pagamento</b><span class="tl">modelo da biblioteca · versão 3</span></div><p>${esc(a.pac)} reconhece o débito de ${fmt(a.orig)} (títulos ${a.tits.join(', ')}), atualizado para ${fmt(a.atual)} em ${x2Dmy(a.d)}, e o pagará com entrada de ${fmt(a.entrada)} e ${a.n} parcelas mensais, conforme a tabela abaixo.</p><div class="x2-lst">${a.parc.map(p=>`<div><span>${p.n?'Parcela '+p.n:'Entrada'} · ${x2Dmy(p.venc)}</span><span>${fmt(p.valor)}</span></div>`).join('')}</div><p class="tl">Dados do estabelecimento vêm do cadastro da unidade (no Clinicas, o endereço estava fixo no modelo). Assinatura no tablet ou aceite por WhatsApp.</p></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn sec" onclick="toast('PDF do termo aberto em nova aba')">${I.dl} PDF</button></div>`)}
function crtQuebrar(id){const a=CRT_ACORDOS.find(x=>x.id===id);x2Mot('Quebrar acordo '+id,'As parcelas em aberto são canceladas e o saldo volta a ser cobrado pelos títulos originais, com a correção da data do acordo. Precisa do gestor.',m=>{a.quebrado=true;a.parc.forEach(p=>{if(p.st!=='paga')p.st='cancelada'});CRT_TIT.filter(t=>a.tits.includes(t.id)).forEach(t=>{t.st='aberto';delete t.acordo});x2Aud('Carteira e cobrança',`Acordo ${id} quebrado: ${m}`);closeDrawer();reView();toast('Acordo quebrado; os títulos voltaram para a cobrança')},'Quebrar acordo','danger')}
/* Novo acordo: valor original + multa + juros calculados; entrada e parcelas pela configuração; "valor combinado" diferente só com o gestor */
function crtAcordoNovo(pac){const nomes=[...new Set(crtAbertos().map(t=>t.pac))];pac=pac&&nomes.includes(pac)?pac:nomes[0];CRT_AC={pac,tits:crtAbertos().filter(t=>t.pac===pac).map(t=>t.id),ent:CRT_CFG.entradaMin,n:3,forma:'Boleto',comb:false};crtAcRender()}
function crtAcCalc(){const A=CRT_AC,ts=CRT_TIT.filter(t=>A.tits.includes(t.id)),orig=r2(ts.reduce((s,t)=>s+t.valor,0)),atual=r2(ts.reduce((s,t)=>s+crtAtual(t).tot,0));const base=A.comb&&A.valComb>0?A.valComb:atual,ent=r2(base*A.ent/100),saldo=r2(base-ent),i=CRT_CFG.jurosParc/100,parc=A.n?r2(i?saldo*i/(1-Math.pow(1+i,-A.n)):saldo/A.n):0;return {ts,orig,atual,base,ent,saldo,parc,total:r2(ent+parc*A.n)}}
function crtAcRender(){const A=CRT_AC,c=crtAcCalc(),nomes=[...new Set(crtAbertos().map(t=>t.pac))];
 openModal(`${mh('Novo acordo de pagamento')}<div class="mb"><div class="field"><label for="acP">Paciente</label><select class="in" id="acP" onchange="crtAcordoNovo(this.value)">${nomes.map(n=>`<option ${n===A.pac?'selected':''}>${esc(n)}</option>`).join('')}</select></div>
 <h4 style="margin:8px 0 4px">Títulos no acordo</h4><div class="at-list">${crtAbertos().filter(t=>t.pac===A.pac).map(t=>`<label class="at-row" style="cursor:pointer"><input type="checkbox" ${A.tits.includes(t.id)?'checked':''} onchange="crtAcTit('${t.id}',this.checked)" style="margin-right:8px"><div class="grow">${esc(t.orig)}<small>${t.id} · ${crtDias(t)>0?crtDias(t)+' dias de atraso':'a vencer'}</small></div><span class="at-price">${fmt(crtAtual(t).tot)}</span></label>`).join('')}</div>
 <div class="formgrid" style="margin-top:8px"><div class="field"><label>Entrada ${info('Mínimo de '+CRT_CFG.entradaMin+'% (configurável em Juros e multa).')}</label><select class="in" onchange="CRT_AC.ent=+this.value;crtAcRender()">${[CRT_CFG.entradaMin,30,40,50].filter((v,i,a)=>a.indexOf(v)===i).map(v=>`<option value="${v}" ${A.ent===v?'selected':''}>${v}%</option>`).join('')}</select></div>
 <div class="field"><label>Parcelas</label><select class="in" onchange="CRT_AC.n=+this.value;crtAcRender()">${Array.from({length:CRT_CFG.parcMax},(_,i)=>i+1).map(v=>`<option value="${v}" ${A.n===v?'selected':''}>${v}×</option>`).join('')}</select></div>
 <div class="field"><label>Forma por parcela</label><select class="in" onchange="CRT_AC.forma=this.value;crtAcRender()">${['Boleto','Pix'].map(v=>`<option ${A.forma===v?'selected':''}>${v}</option>`).join('')}</select></div></div>
 <div class="f2-cascata" style="margin-top:8px"><div><span>Valor original</span><span>${fmt(c.orig)}</span></div><div><span>Multa e juros até hoje<small>${CRT_CFG.multa}% + ${CRT_CFG.juros}% a.m. pro rata</small></span><span>${fmt(r2(c.atual-c.orig))}</span></div><div><span>Atualizado</span><span>${fmt(c.atual)}</span></div>${A.comb&&A.valComb>0?`<div><span>Valor combinado (gestor)</span><span>${fmt(A.valComb)}</span></div>`:''}<div><span>Entrada (${A.ent}%)</span><span>${fmt(c.ent)}</span></div><div><span>${A.n}× de<small>juros do parcelamento ${CRT_CFG.jurosParc}% a.m. (tabela Price)</small></span><span>${fmt(c.parc)}</span></div><div class="tot"><span>Total do acordo</span><span>${fmt(c.total)}</span></div></div>
 <label class="check" style="margin-top:8px"><input type="checkbox" ${A.comb?'checked':''} onchange="CRT_AC.comb=this.checked;crtAcRender()">Valor combinado diferente do calculado ${info('Único valor que se digita na Carteira. Exige a aprovação de um gestor, com senha, e fica na trilha.')}</label>
 ${A.comb?`<div class="formgrid"><div class="field"><label for="acV">Valor combinado</label><input class="in" id="acV" inputmode="decimal" value="${A.valComb?String(A.valComb).replace('.',','):''}" placeholder="0,00" onchange="CRT_AC.valComb=naNum(this.value)||0;crtAcRender()"></div><div class="field"><label for="acG">Gestor</label><select class="in" id="acG"><option>Lúcia (gestora)</option><option>Jânio (administrador)</option></select></div><div class="field"><label for="acS">Senha do gestor</label><input class="in" id="acS" type="password" placeholder="no protótipo, qualquer uma"></div></div>`:''}
 <div class="field"><label for="acM">Motivo <span class="req">*</span></label><textarea class="in" id="acM" rows="2" placeholder="Ex.: paciente pediu parcelamento na régua D+60"></textarea></div></div>
 <div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="crtAcOk()">Criar acordo e enviar o termo</button></div>`)}
function crtAcTit(id,v){const A=CRT_AC;if(v&&!A.tits.includes(id))A.tits.push(id);if(!v)A.tits=A.tits.filter(x=>x!==id);crtAcRender()}
function crtAcOk(){const A=CRT_AC,c=crtAcCalc(),m=($('#acM').value||'').trim();if(!A.tits.length){toast('Escolha pelo menos um título','warn');return}if(m.length<10){toast('Escreva o motivo (pelo menos 10 letras)','warn');$('#acM').focus();return}
 let aprov='automático (dentro da política)';if(A.comb){if(!(A.valComb>0)){toast('Informe o valor combinado','warn');return}if(!($('#acS').value||'')){toast('O valor combinado precisa da senha do gestor','warn');$('#acS').focus();return}aprov=$('#acG').value}
 const id='AC-00'+(32+CRT_ACORDOS.length-2),ven=i=>{const d=new Date(PL_HOJE+'T12:00');d.setMonth(d.getMonth()+i);return d.toISOString().slice(0,10)};
 CRT_ACORDOS.unshift({id,pac:A.pac,tits:A.tits.slice(),orig:c.orig,atual:c.base,entrada:c.ent,n:A.n,forma:A.forma,aprov,d:PL_HOJE,mot:m,parc:[{n:0,venc:PL_HOJE,valor:c.ent,st:'aberta',forma:'Pix'},...Array.from({length:A.n},(_,i)=>({n:i+1,venc:ven(i+1),valor:c.parc,st:'aberta',forma:A.forma}))]});
 CRT_TIT.filter(t=>A.tits.includes(t.id)).forEach(t=>{t.st='acordo';t.acordo=id});x2Aud('Carteira e cobrança',`Acordo ${id} (${A.pac}): ${fmt(c.base)}${A.comb?' combinado':''}, entrada ${fmt(c.ent)} e ${A.n}× ${fmt(c.parc)} (${A.forma}); aprovado por ${aprov}. Motivo: ${m}`);
 CRT_AC=null;closeModal();CRT_ABA='acordos';if(location.hash==='#carteira')reView();toast(`Acordo ${id} criado; termo enviado para assinatura por WhatsApp`)}
function crtRegua(){return `<div class="grid g2"><div class="card at-card"><h3>Etapas da régua ${info('Roda todo dia às 8h. No máximo 1 mensagem por dia por paciente, só em horário comercial (8h às 20h, sem domingo), respeitando quem pediu para não receber. Menor de idade: vai para o responsável.')}</h3><div class="sub">Do vencimento em diante</div>
 ${CRT_REGUA.map((r,i)=>`<div class="switchrow"><div><b>${r.d>=0?'D+'+r.d:'D'+r.d} · ${r.c}</b><small>${r.fut?'Fase futura: integração com birô de crédito, depois de aviso formal com prazo.':esc((CRT_MOD[r.m]||['',''])[0])+(r.lig?' · cria tarefa de ligação para a recepção':'')}</small></div><label class="switch"><input type="checkbox" ${r.on?'checked':''} ${r.fut?'disabled':''} onchange="crtReguaTog(${i},this.checked)"><span class="tr"></span></label></div>`).join('')}
 <div class="row" style="margin-top:10px"><button class="btn sec" onclick="crtReguaRodar()">Rodar a régua agora (simulação)</button></div></div>
 <div class="card at-card"><h3>Modelos de mensagem ${info('Variáveis: {nome}, {valor}, {vencimento}, {origem}, {atualizado}, {link}, {entrada}, {parcelas}. Modelos de WhatsApp aprovados na Meta pelo 360dialog.')}</h3><div class="sub">Clique para ver ou editar</div><div class="at-list">${Object.entries(CRT_MOD).map(([k,[t,s]])=>`<div class="at-row clk" onclick="crtModelo('${k}')"><div class="grow">${esc(t)}<small>${esc(s.slice(0,90))}…</small></div></div>`).join('')}</div></div></div>
 <h3 style="margin:16px 0 8px">Últimos envios</h3>${tabela(['Quando','Para','Título','Canal','Modelo','Resultado'],CRT_ENV.map(e=>`<tr>${td('Quando',e.h)}${td('Para',esc(e.pac))}${td('Título',`<span class="mono">${e.tit}</span>`)}${td('Canal',e.c)}${td('Modelo',esc((CRT_MOD[e.m]||['—'])[0]))}${td('Resultado',`<span class="${/falhou/.test(e.st)?'prazo-err':/respond|lida/.test(e.st)?'prazo-ok':''}">${esc(e.st)}</span>`)}</tr>`),'Nenhum envio')}`}
function crtReguaTog(i,v){const r=CRT_REGUA[i];x2Mot((v?'Ligar':'Desligar')+' etapa '+(r.d>=0?'D+'+r.d:'D'+r.d),'Muda a cobrança de todos os pacientes a partir de amanhã.',m=>{r.on=v;x2Aud('Carteira e cobrança',`Etapa ${r.d>=0?'D+'+r.d:'D'+r.d} (${r.c}) ${v?'ligada':'desligada'}: ${m}`);reView();toast('Régua atualizada')},'Confirmar');setTimeout(()=>{const b=$('#modal .ghost');if(b)b.onclick=()=>{closeModal();reView()}},0)}
function crtModelo(k){const [t,s]=CRT_MOD[k];const ex=CRT_TIT.find(x=>x.st==='aberto'&&crtDias(x)>0);openModal(`${mh('Modelo · '+esc(t))}<div class="mb"><div class="field"><label for="crtMt">Texto</label><textarea class="in" id="crtMt" rows="4">${esc(s)}</textarea></div><h4 style="margin:8px 0 4px">Prévia com ${esc(ex.pac)}</h4><div class="x2-msg">${esc(crtTpl(s,ex))}</div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="CRT_MOD['${k}'][1]=$('#crtMt').value;x2Aud('Carteira e cobrança','Modelo &quot;${esc(t)}&quot; editado; WhatsApp reenviado para aprovação na Meta');closeModal();reView();toast('Modelo salvo; o WhatsApp volta para aprovação na Meta antes de usar')">Salvar</button></div>`)}
function crtReguaRodar(){const l=crtAbertos().filter(t=>crtDias(t)>=-3);let n=0;l.forEach(t=>{const d=crtDias(t),st=CRT_REGUA.find(r=>r.on&&!r.fut&&r.d===d);if(st){CRT_ENV.unshift({h:'04/11 '+hhmm(new Date()),pac:t.resp||t.pac,tit:t.id,c:st.c,m:st.m,st:'enviada'});n++}});x2Aud('Carteira e cobrança',`Régua rodada à mão: ${n} mensagens`);reView();toast(n?n+' mensagens enviadas pela régua (as outras já receberam hoje)':'Ninguém está numa etapa da régua hoje: nada enviado')}
function crtNegat(){return `<div class="card at-card"><div class="figrow">${typeof FIG==='function'?FIG('ok'):''}<div><h3>Negativação · fase futura</h3><div class="sub">Ainda não liga com nenhum birô de crédito</div>
 <p style="font-size:14px">Quando ligar: só títulos com mais de 90 dias, depois do aviso formal com prazo para pagar, com aprovação do gestor por título e baixa automática no birô quando o pagamento conciliar. Menor de idade e dependente de plano nunca são negativados; o responsável financeiro sim.</p>
 <div class="x2-lst" style="margin-top:8px">${crtAbertos().filter(t=>crtDias(t)>90).map(t=>`<div><span>${esc(t.pac)} · ${t.id}</span><span>${crtDias(t)} dias · ${fmt(crtAtual(t).tot)}</span></div>`).join('')||'<div><span>Nenhum título com mais de 90 dias</span><span></span></div>'}</div>
 <p class="tl" style="margin-top:8px">Hoje esses títulos ficam na régua (proposta de acordo) e na lista de ligação da recepção.</p></div></div></div>`}
function crtConfig(){x2Mot('Juros, multa e acordo','Vale para títulos que vencerem a partir de amanhã e para acordos novos; o que já foi acordado não muda.',(m,x)=>{['multa','juros','jurosParc','parcMax','entradaMin','tolerancia'].forEach(k=>{if(x[k]!==undefined&&x[k]!=='')CRT_CFG[k]=+x[k]});x2Aud('Carteira e cobrança',`Configuração alterada: multa ${CRT_CFG.multa}%, juros ${CRT_CFG.juros}% a.m., parcelamento ${CRT_CFG.jurosParc}% a.m., até ${CRT_CFG.parcMax}×, entrada mínima ${CRT_CFG.entradaMin}%. Motivo: ${m}`);reView();toast('Configuração salva')},'Salvar','',
 `<div class="formgrid">${[['multa','Multa (%)',[0,1,2]],['juros','Juros de mora (% ao mês)',[0,0.5,1]],['jurosParc','Juros do parcelamento (% ao mês)',[0,1,1.5,2]],['parcMax','Parcelas no máximo',[3,6,10,12]],['entradaMin','Entrada mínima (%)',[0,10,20,30]],['tolerancia','Tolerância (dias)',[0,3,5]]].map(([k,l,o])=>`<div class="field"><label>${l}</label><select class="in" data-x2="${k}">${o.map(v=>`<option value="${v}" ${CRT_CFG[k]===v?'selected':''}>${String(v).replace('.',',')}</option>`).join('')}</select></div>`).join('')}</div><p class="tl">Multa limitada a 2% e juros de mora a 1% ao mês nas cobranças ao consumidor (o sistema não deixa passar disso).</p>`)}
GUIDES.carteira=['Inadimplência: os títulos em atraso por faixa (0–30, 31–60, 61–90, 90+). Clique numa faixa para filtrar; o valor atualizado já tem multa e juros calculados.','Cobrar manda a mensagem da etapa da régua pelo WhatsApp ou e-mail; Acordo abre o parcelamento com os valores calculados.','Por paciente: crédito, títulos e acordos de cada um. Crédito nasce de um adiantamento ou de uma devolução e pode abater um título.','Régua de cobrança: ligue ou desligue as etapas e edite os modelos. Toda mudança pede motivo e vai para a trilha.'];
REGRAS['Carteira e cobrança']={aba:'Financeiro · Clinicas §8.1 (crédito, inadimplência, TCD) redesenhado',itens:[['Valores','Multa, juros, entrada e parcelas são calculados; nenhum valor é digitado, exceto o valor combinado de um acordo, que exige a senha de um gestor e fica na trilha.'],['Origem','Todo título tem origem (atendimento, mensalidade de plano ou parcela de acordo). No Clinicas a inadimplência era "lançada" solta e entrava no caixa por uma fusão confusa.'],['Crédito','Nasce de um adiantamento recebido no caixa ou de uma devolução como crédito; sai por uso num título, devolução pelo meio original ou transferência aprovada pelo gestor. Nada se exclui.'],['Acordo','Substitui o TCD: títulos entram no acordo, parcelas viram títulos com boleto ou Pix, termo vem da biblioteca de modelos (sem endereço fixo). Baixa só pela conciliação. Quebrar volta os títulos.'],['Faixas','0–30, 31–60, 61–90 e mais de 90 dias, pela data de vencimento.'],['Régua','Uma mensagem por dia por paciente, em horário comercial, respeitando o descadastro; menor de idade vai para o responsável; modelos de WhatsApp aprovados na Meta.'],['Negativação','Fase futura: só depois de aviso formal, com aprovação por título e baixa automática.'],['Trilha','Toda escrita (cobrança, contato, crédito, acordo, configuração) pede motivo e vai para a trilha de auditoria.']]};

