const rdeItem=(e)=>{if(e.dir==='rec'){const p=PROC(e.c);return {n:p?p.n:e.c,v:p?p.preco:0}}const it=(RDE_P(e.parc).cat.find(x=>x[0]===e.c)||[e.c,e.c,0]);return {n:it[1],v:it[2]}};
function rdeValor(regra,bruto){if(typeof rpValor==='function')return rpValor(regra,bruto,0);const imp=typeof F2_IMP!=='undefined'?F2_IMP:8.65;return r2(regra.tipo==='%'?(regra.base==='líquido'?bruto*(1-imp/100):bruto)*regra.val/100:regra.val)}
const rdeRegraTxt=r=>r.tipo==='%'?r.val+'% do '+r.base:r.tipo==='fixo'?fmt(r.val)+' fixo':fmt(r.val)+' por exame';
/* Participação de quem encaminhou e o que cada lado deve: pago aqui → devemos ao executor (valor − participação); pago no parceiro → ele nos deve a participação */
function rdeConta(e){const it=rdeItem(e),regra=e.dir==='env'?RDE_P(e.parc).regra:RDE_NOSSO.regra,part=e.st==='cancelado'?0:rdeValor(regra,it.v);let saldo=0;
 if(e.st!=='cancelado'&&e.st!=='agendado'){const v=it.v;saldo=e.dir==='env'?(e.pago==='aqui'?-(v-part):part):(e.pago==='aqui'?-part:v-part)}
 return {it,regra,part,saldo:r2(saldo)}}
const RDE_FAT=[{id:'FT-2026-10-R1',parc:'R1',mes:'out/2026',st:'conferida',cont:1},{id:'FT-2026-10-R2',parc:'R2',mes:'out/2026',st:'aberta'},{id:'FT-2026-10-R3',parc:'R3',mes:'out/2026',st:'aberta'},{id:'FT-2026-10-R4',parc:'R4',mes:'out/2026',st:'aprovada'}];
const rdeFatItens=f=>RDE_ENC.filter(e=>e.parc===f.parc&&e.d.slice(0,7)==='2026-10'&&e.st!=='cancelado');
const rdeFatSaldo=f=>r2(rdeFatItens(f).filter(e=>!e.contestado).reduce((s,e)=>s+rdeConta(e).saldo,0));
let RDE_ABA='parceiros',RDE_Q='',RDE_AGP='R1',RDE_EN=null;
VIEWS.rede=()=>{const env=RDE_ENC.filter(e=>e.dir==='env'&&e.st!=='cancelado').length,rec=RDE_ENC.filter(e=>e.dir==='rec').length,abertas=RDE_FAT.filter(f=>f.st!=='aprovada');
 return `${pageHead('Rede e parceiros','Rede de clínicas','Clínicas parceiras com catálogo compartilhado: encaminhe o paciente para o que a sua unidade não faz, veja a agenda do parceiro, e a participação sai calculada pela mesma regra do repasse. Faturas entre clínicas e qualidade de cada parceiro. Dados de exemplo.',`${rulesBtn('Rede de clínicas')}${x2TrilhaBtn('Rede de clínicas')}<button class="btn" onclick="rdeEncaminhar()">Encaminhar paciente</button>`)}
<div class="mini" style="margin-bottom:12px">${miniKpi('Parceiros',RDE_PARC.length,RDE_PARC.reduce((s,p)=>s+p.cat.length,0)+' procedimentos no catálogo','',"RDE_ABA='catalogo';reView()")}${miniKpi('Encaminhados',env,'por nós, últimos 30 dias','',"RDE_ABA='enc';reView()")}${miniKpi('Recebidos',rec,'de parceiros para nós','ok',"RDE_ABA='enc';reView()")}${miniKpi('Faturas a resolver',abertas.length,'outubro/2026',abertas.length?'warn':'ok',"RDE_ABA='faturas';reView()")}</div>
${x2Tabs('RDE_ABA',[['parceiros','Parceiros'],['catalogo','Catálogo da rede'],['enc','Encaminhamentos'],['agenda','Agenda do parceiro'],['faturas','Faturas entre clínicas',abertas.length?{v:abertas.length,c:'warn'}:null],['qualidade','Qualidade e prazo']],RDE_ABA)}
${RDE_ABA==='parceiros'?rdeParceiros():RDE_ABA==='catalogo'?rdeCatalogo():RDE_ABA==='enc'?rdeEncs():RDE_ABA==='agenda'?rdeAgenda():RDE_ABA==='faturas'?rdeFaturas():rdeQualidade()}
${piada(174,{todos:'Encaminhar para a rede é como indicar um restaurante: se o paciente gostar, a gente ganha participação; se não gostar, a gente ganha uma reclamação. A qualidade do parceiro está na última aba.'})}`};
function rdeParceiros(){return `<div class="x2-cards">${RDE_PARC.map(p=>`<div class="x2-k"><h4>${esc(p.n)}</h4><span class="tl">${esc(p.cidade)} · ${String(p.km).replace('.',',')} km · contrato ${p.contrato}</span>
 <div class="x2-lst"><div><span>Participação de quem encaminha ${info('Mesma regra do Repasse médico: percentual (bruto ou líquido de impostos), fixo ou por exame. Calculada item a item; ninguém digita.')}</span><span>${rdeRegraTxt(p.regra)}</span></div><div><span>Prazo de laudo (contrato)</span><span>${p.sla.laudo?p.sla.laudo+' h':'—'}</span></div><div><span>Laudo no prazo</span><span class="${p.q.prazo>=90?'prazo-ok':p.q.prazo>=80?'prazo-warn':'prazo-err'}">${p.q.prazo}%</span></div><div><span>Procedimentos no catálogo</span><span>${p.cat.length}</span></div></div>
 <div class="row" style="gap:6px"><button class="btn sm sec" onclick="RDE_Q='${esc(p.n.split(' ')[0])}';RDE_ABA='catalogo';reView()">Catálogo</button><button class="btn sm sec" onclick="RDE_AGP='${p.id}';RDE_ABA='agenda';reView()">Agenda</button><button class="btn sm" onclick="rdeEncaminhar({parc:'${p.id}'})">Encaminhar</button></div></div>`).join('')}
 <div class="x2-k"><h4>DeoClinic · Unidade Central (nós)</h4><span class="tl">O que oferecemos à rede, vindo de Procedimentos</span><div class="x2-lst">${RDE_NOSSO.itens.map(c=>`<div><span>${esc(PROC(c).n)}</span><span>${fmt(PROC(c).preco)}</span></div>`).join('')}</div><span class="tl">Participação que pagamos a quem nos encaminha: ${rdeRegraTxt(RDE_NOSSO.regra)}</span></div></div>`}
function rdeCatalogo(){const q=semAc(RDE_Q.trim());const l=[...RDE_PARC.flatMap(p=>p.cat.map(c=>({p,c:c[0],n:c[1],v:c[2],prazo:c[3]}))),...RDE_NOSSO.itens.map(c=>({p:null,c,n:PROC(c).n,v:PROC(c).preco,prazo:PROC(c).tipo==='Imagem'?'24 h':'—'}))].filter(x=>!q||semAc(x.n+' '+x.c+' '+(x.p?x.p.n:'deoclinic nós')).includes(q)).sort((a,b)=>a.n.localeCompare(b.n));
 return `<div class="fbar">${x2Busca('rdeQ',RDE_Q,'Buscar procedimento, código ou clínica',"RDE_Q=this.value;reView();x2Foco('rdeQ')")}<span class="tl">${info('Preço de rede combinado em contrato; quando o paciente paga aqui, o sistema calcula o que vai para o parceiro. Códigos TUSS de exemplo.')}</span></div>
 ${tabela(['Procedimento','TUSS','Onde','Distância','Preço de rede','Prazo do laudo','Próxima vaga',''],l.map(x=>`<tr>${td('Procedimento',`<b>${esc(x.n)}</b>`)}${td('TUSS',`<span class="mono">${x.c}</span>`)}${td('Onde',x.p?esc(x.p.n):'<span class="badge ok">nós</span>')}${td('Distância',x.p?String(x.p.km).replace('.',',')+' km':'—')}${td('Preço de rede',fmt(x.v))}${td('Prazo do laudo',esc(x.prazo))}${td('Próxima vaga',x.p?rdeSlots(x.p.id)[0].d+' '+rdeSlots(x.p.id)[0].h:'hoje')}${td('',x.p?`<button class="btn sm sec" onclick="rdeEncaminhar({parc:'${x.p.id}',c:'${x.c}'})">Encaminhar</button>`:'')}</tr>`),'Nada no catálogo com essa busca')}`}
function rdeEncs(){return tabela(['Encaminhamento','Sentido','Paciente','Procedimento','Clínica','Quando','Situação','Participação','Saldo entre clínicas'],RDE_ENC.map(e=>{const c=rdeConta(e),p=RDE_P(e.parc);return `<tr class="clk" onclick="rdeEnc('${e.id}')">${td('Encaminhamento',`<span class="mono">${e.id}</span>`)}${td('Sentido',e.dir==='env'?'<span class="badge info">enviado</span>':'<span class="badge ok">recebido</span>')}${td('Paciente',esc(e.pac))}${td('Procedimento',esc(c.it.n))}${td('Clínica',esc(p.n))}${td('Quando',x2Dmy(e.d)+' '+e.h)}${td('Situação',`<span class="badge ${e.st==='cancelado'?'neutral':e.st==='agendado'?'acc':'ok'}">${e.st}</span>${e.contest?' <span class="badge warn">contestado</span>':''}`)}${td('Participação',e.st==='cancelado'?'—':fmt(c.part))}${td('Saldo entre clínicas',e.st==='agendado'||e.st==='cancelado'?'<span class="tl">—</span>':c.saldo>=0?`<span class="f2-mais">a receber ${fmt(c.saldo)}</span>`:`<span class="f2-menos">a pagar ${fmt(-c.saldo)}</span>`)}</tr>`}),'Nenhum encaminhamento')}
function rdeEnc(id){const e=RDE_ENC.find(x=>x.id===id),c=rdeConta(e),p=RDE_P(e.parc);openDrawer(e.id+' · '+esc(e.pac.split(' ')[0]),`${kvs([['Sentido',e.dir==='env'?'Nós encaminhamos; '+esc(p.n)+' executa':esc(p.n)+' encaminhou; nós executamos'],['Paciente',esc(e.pac)],['Procedimento',esc(c.it.n)+' · '+fmt(c.it.v)],['Quando',x2Dmy(e.d)+' às '+e.h],['Situação',esc(e.st)],['Pago',e.pago==='aqui'?'aqui, na DeoClinic':e.pago==='parceiro'?'no parceiro':'—'],e.orig?['Origem',esc(e.orig)]:null,['Regra',rdeRegraTxt(c.regra)+' (mesma conta do repasse)'],['Participação',fmt(c.part)],['Saldo',c.saldo>=0?'a receber '+fmt(c.saldo):'a pagar '+fmt(-c.saldo)],e.contest?['Contestação',esc(e.contest)]:null])}
 <p class="tl" style="margin-top:8px">Dados do paciente compartilhados com o parceiro só com o consentimento registrado no encaminhamento (nome, CPF, telefone e o pedido médico).</p>
 ${e.st==='agendado'?`<div class="row" style="margin-top:12px;gap:6px"><button class="btn sec" onclick="toast('Lembrete com o endereço e o preparo do parceiro enviado por WhatsApp')">Reenviar orientações</button><button class="btn ghost" style="color:var(--err)" onclick="rdeCancelar('${e.id}')">Cancelar</button></div>`:''}`)}
function rdeCancelar(id){const e=RDE_ENC.find(x=>x.id===id);x2Mot('Cancelar '+id,'O parceiro recebe o cancelamento pela integração e a vaga é liberada na agenda dele.',m=>{e.st='cancelado';x2Aud('Rede de clínicas',`${id} cancelado: ${m}`);closeDrawer();reView();toast('Encaminhamento cancelado; parceiro avisado')},'Cancelar encaminhamento','danger')}
function rdeSlots(pid){const b=['07:30','08:20','09:10','10:00','10:50','14:00','15:00','16:10'];const out=[];['05/11','06/11','09/11'].forEach((d,j)=>b.forEach((h,i)=>{const oc=(i*7+j*3+pid.charCodeAt(1))%3===0||RDE_ENC.some(e=>e.parc===pid&&e.st==='agendado'&&e.d==='2026-'+d.slice(3)+'-'+d.slice(0,2)&&e.h===h);if(!oc)out.push({d,h})}));return out}
function rdeAgenda(){const p=RDE_P(RDE_AGP),livres=rdeSlots(p.id),b=['07:30','08:20','09:10','10:00','10:50','14:00','15:00','16:10'];
 return `<div class="row" style="gap:6px;margin-bottom:10px">${RDE_PARC.map(x=>chip(x.n,RDE_AGP===x.id,`RDE_AGP='${x.id}';reView()`)).join('')}</div>
 <p class="tl" style="margin-bottom:8px">Agenda de ${esc(p.n)} pela integração (a mesma agenda que o parceiro usa, sem "agenda de credenciado" paralela). Clique num horário livre para encaminhar. ${info('A vaga fica reservada por 10 minutos enquanto você conclui; se não concluir, volta para o parceiro.')}</p>
 <div class="x2-grade">${['05/11','06/11','09/11'].map(d=>`<div class="dia"><h4>${d}</h4><div class="x2-slots">${b.map(h=>{const ok=livres.some(s=>s.d===d&&s.h===h);return `<button class="x2-slot ${ok?'':'oc'}" ${ok?`onclick="rdeEncaminhar({parc:'${p.id}',slot:'${d} ${h}'})"`:'disabled'}>${h}<small>${ok?'livre':'ocupado'}</small></button>`}).join('')}</div></div>`).join('')}</div>`}
function rdeEncaminhar(o){o=o||{};const p=RDE_P(o.parc||'R1');RDE_EN={parc:p.id,c:o.c||p.cat[0][0],slot:o.slot||'',pac:'',pago:'aqui',cons:false};rdeEnRender()}
function rdeEnRender(){const E=RDE_EN,p=RDE_P(E.parc),it=p.cat.find(x=>x[0]===E.c)||p.cat[0],part=rdeValor(p.regra,it[2]),sl=rdeSlots(p.id).slice(0,8);
 openModal(`${mh('Encaminhar paciente para a rede')}<div class="mb"><div class="formgrid"><div class="field"><label>Paciente <span class="req">*</span></label><select class="in" onchange="RDE_EN.pac=this.value;rdeEnRender()"><option value="">Escolha</option>${PACIENTES.filter(x=>x.ativo).map(x=>`<option ${E.pac===x.n?'selected':''}>${esc(x.n)}</option>`).join('')}</select></div>
 <div class="field"><label>Clínica</label><select class="in" onchange="RDE_EN.parc=this.value;RDE_EN.c=RDE_P(this.value).cat[0][0];RDE_EN.slot='';rdeEnRender()">${RDE_PARC.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.n)}</option>`).join('')}</select></div>
 <div class="field"><label>Procedimento</label><select class="in" onchange="RDE_EN.c=this.value;rdeEnRender()">${p.cat.map(x=>`<option value="${x[0]}" ${x[0]===it[0]?'selected':''}>${esc(x[1])} · ${fmt(x[2])}</option>`).join('')}</select></div></div>
 <h4 style="margin:8px 0 4px">Horário na agenda do parceiro</h4><div class="x2-slots">${sl.map(s=>`<button class="x2-slot ${E.slot===s.d+' '+s.h?'on':''}" onclick="RDE_EN.slot='${s.d} ${s.h}';rdeEnRender()">${s.h}<small>${s.d}</small></button>`).join('')}</div>
 <div class="row" style="gap:6px;margin-top:10px">${chip('Paga aqui (repassamos ao parceiro)',E.pago==='aqui',"RDE_EN.pago='aqui';rdeEnRender()")}${chip('Paga no parceiro',E.pago==='parceiro',"RDE_EN.pago='parceiro';rdeEnRender()")}</div>
 <div class="f2-cascata" style="margin-top:10px"><div><span>Preço de rede</span><span>${fmt(it[2])}</span></div><div><span>Nossa participação<small>${rdeRegraTxt(p.regra)} · regra do contrato ${p.contrato}</small></span><span>${fmt(part)}</span></div><div class="tot"><span>${E.pago==='aqui'?'Vai para o parceiro na fatura':'O parceiro nos deve na fatura'}</span><span>${fmt(E.pago==='aqui'?r2(it[2]-part):part)}</span></div></div>
 <label class="check" style="margin-top:10px"><input type="checkbox" ${E.cons?'checked':''} onchange="RDE_EN.cons=this.checked">O paciente autorizou compartilhar nome, CPF, telefone e o pedido médico com ${esc(p.n)} <span class="req">*</span> ${info('Consentimento LGPD para o compartilhamento com outra clínica, registrado com data, hora e quem colheu. Sem ele, o encaminhamento não sai.')}</label></div>
 <div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="rdeEnOk()">Encaminhar</button></div>`)}
function rdeEnOk(){const E=RDE_EN;if(!E.pac){toast('Escolha o paciente','warn');return}if(!E.slot){toast('Escolha um horário na agenda do parceiro','warn');return}if(!E.cons){toast('Registre o consentimento do paciente para compartilhar os dados','warn');return}
 const [d,h]=E.slot.split(' '),id='EN-0'+(120+RDE_ENC.filter(e=>+e.id.slice(3)>=120).length);RDE_ENC.unshift({id,dir:'env',parc:E.parc,pac:E.pac,c:E.c,d:'2026-'+d.slice(3)+'-'+d.slice(0,2),h,st:'agendado',pago:E.pago});
 x2Aud('Rede de clínicas',`${id}: ${E.pac} encaminhado para ${RDE_P(E.parc).n} em ${E.slot} (consentimento registrado)`);RDE_EN=null;closeModal();RDE_ABA='enc';if(location.hash==='#rede')reView();toast(`Encaminhado: ${id}. O paciente recebe endereço, horário e preparo por WhatsApp`)}
function rdeFaturas(){return tabela(['Fatura','Parceiro','Mês','Itens','Saldo','Situação',''],RDE_FAT.map(f=>{const s=rdeFatSaldo(f),n=rdeFatItens(f).length;return `<tr class="clk" onclick="rdeFat('${f.id}')">${td('Fatura',`<span class="mono">${f.id}</span>`)}${td('Parceiro',esc(RDE_P(f.parc).n))}${td('Mês',f.mes)}${td('Itens',n)}${td('Saldo',s>=0?`<span class="f2-mais">a receber ${fmt(s)}</span>`:`<span class="f2-menos">a pagar ${fmt(-s)}</span>`)}${td('Situação',`<span class="badge ${f.st==='aprovada'?'ok':f.st==='conferida'?'info':'warn'}">${f.st}</span>`)}${td('',`<button class="btn sm sec" onclick="event.stopPropagation();rdeFat('${f.id}')">Conferir</button>`)}</tr>`}),'Nenhuma fatura')+`<p class="tl" style="margin-top:8px">Saldo líquido do mês: encaminhamentos pagos aqui (pagamos ao executor, menos a nossa participação) e pagos no parceiro (ele nos paga a participação). Aprovada, vira conta a pagar ou a receber no Financeiro.</p>`}
function rdeFat(id){const f=RDE_FAT.find(x=>x.id===id),l=rdeFatItens(f),s=rdeFatSaldo(f);openDrawer('Fatura '+id,`${kvs([['Parceiro',esc(RDE_P(f.parc).n)],['Mês',f.mes],['Situação',f.st],['Saldo',s>=0?'a receber '+fmt(s):'a pagar '+fmt(-s)]])}
 <div class="at-list" style="margin-top:10px">${l.map(e=>{const c=rdeConta(e);return `<div class="at-row"><div class="grow">${esc(e.pac)} · ${esc(c.it.n)}<small>${e.id} · ${x2Dmy(e.d)} · ${e.dir==='env'?'enviado':'recebido'} · pago ${e.pago==='aqui'?'aqui':'no parceiro'}${e.contestado?' · <b>contestado</b>: '+esc(e.contestado):''}</small></div><span class="at-price">${c.saldo>=0?'+ ':'− '}${fmt(Math.abs(c.saldo))}</span>${f.st!=='aprovada'&&!e.contestado?`<button class="btn sm ghost" onclick="rdeContestar('${id}','${e.id}')">Contestar</button>`:''}</div>`}).join('')||'<p class="tl">Sem itens no mês.</p>'}</div>
 ${f.st!=='aprovada'?`<div class="row" style="margin-top:12px;gap:6px">${f.st==='aberta'?`<button class="btn sec" onclick="rdeFatSt('${id}','conferida')">Marcar como conferida</button>`:''}<button class="btn" onclick="rdeFatSt('${id}','aprovada')">Aprovar e lançar no Financeiro</button></div>`:'<p class="tl" style="margin-top:10px">Aprovada: lançada no Financeiro.</p>'}`)}
function rdeContestar(fid,eid){const e=RDE_ENC.find(x=>x.id===eid);x2Mot('Contestar '+eid,'O item sai do saldo desta fatura até o parceiro responder. O parceiro vê a contestação no portal dele.',m=>{e.contestado=m;x2Aud('Rede de clínicas',`${eid} contestado na fatura ${fid}: ${m}`);rdeFat(fid);reView();toast('Item contestado; parceiro avisado')},'Contestar')}
function rdeFatSt(id,st){const f=RDE_FAT.find(x=>x.id===id),s=rdeFatSaldo(f);x2Mot((st==='aprovada'?'Aprovar ':'Conferir ')+id,st==='aprovada'?`Vira ${s>=0?'conta a receber':'conta a pagar'} de ${fmt(Math.abs(s))} no Financeiro, com vencimento no dia 10. Quem conferiu não aprova (exceto o Administrador).`:'Confere item a item; contestados ficam fora do saldo.',m=>{f.st=st;x2Aud('Rede de clínicas',`Fatura ${id} ${st}: ${m}`);closeDrawer();reView();toast(st==='aprovada'?'Fatura aprovada e lançada no Financeiro':'Fatura conferida')},st==='aprovada'?'Aprovar':'Conferir')}
function rdeQualidade(){const met=[['Laudo no prazo','prazo','%',90,1],['Satisfação (NPS)','nps','',60,1],['Faltas','noshow','%',10,0],['Reclamações (30 dias)','recl','',2,0],['Recusas de agendamento','recusa','%',5,0]];
 return `<p class="tl" style="margin-bottom:8px">Medido pela própria rede: horário do laudo entregue, pesquisa enviada ao paciente depois do atendimento, faltas e reclamações. Abaixo da meta por 2 meses, o parceiro sai do topo do catálogo e o gestor recebe aviso.</p>`+tabela(['Parceiro','Contrato (laudo · agendar)',...met.map(m=>m[0]+' · meta '+(m[4]?'≥ ':'≤ ')+m[3]+m[2])],RDE_PARC.map(p=>`<tr>${td('Parceiro',`<b>${esc(p.n)}</b>`)}${td('Contrato (laudo · agendar)',`${p.sla.laudo?p.sla.laudo+' h':'—'} · ${p.sla.agendar} h`)}${met.map(m=>{const v=p.q[m[1]],ok=m[4]?v>=m[3]:v<=m[3];return td(m[0],`<span class="${ok?'prazo-ok':'prazo-err'}">${v}${m[2]}</span>`)}).join('')}</tr>`))}
GUIDES.rede=['Parceiros: cada clínica da rede, a regra de participação e o prazo de laudo do contrato.','Catálogo da rede: busque o que a sua unidade não faz e veja onde há, com preço de rede, prazo e próxima vaga.','Encaminhar: escolha o paciente, o procedimento e o horário na agenda do parceiro; registre o consentimento para compartilhar os dados. A participação sai calculada.','Faturas: no fim do mês, confira item a item, conteste o que não bate e aprove; vira conta a pagar ou a receber no Financeiro.'];
REGRAS['Rede de clínicas']={aba:'Rede e parceiros · Clinicas §14 (Interclinicas) redesenhado',itens:[['Catálogo','Cada parceiro publica o que faz, com preço de rede e prazo de laudo do contrato; a DeoClinic publica o que oferece, vindo de Procedimentos.'],['Agenda','Pela integração, a agenda real do parceiro (no Clinicas havia uma "agenda de credenciado" paralela). A vaga fica reservada 10 minutos.'],['Participação','Mesma regra do Repasse médico (%, fixo ou por exame; base bruto ou líquido), calculada item a item; ninguém digita.'],['Consentimento','Compartilhar dados com outra clínica exige o consentimento do paciente no encaminhamento (LGPD), com data, hora e quem colheu.'],['Fatura','Saldo líquido por parceiro e mês; item contestado sai do saldo até a resposta; quem confere não aprova; aprovada vira título no Financeiro.'],['Pagamento','Sem postback simulado: a confirmação de pagamento vem da conciliação ou da integração do parceiro (o Clinicas tinha um postback_mockado em produção).'],['Qualidade','Prazo de laudo, satisfação, faltas, reclamações e recusas, com meta; abaixo da meta por 2 meses, aviso ao gestor.']]};

