function apxParceiros(){return tabela(['Parceiro','Tipo','Ambiente','Client ID','Segredo','Rotação','Limite','Situação',''],APX_PARC.map(p=>{const d=apxDiasExp(p);return `<tr class="clk" onclick="apxAbrir('${p.id}')">${td('Parceiro',`<b>${esc(p.n)}</b><small class="tl" style="display:block">${esc(p.contrato)}</small>`)}${td('Tipo',esc(p.tipo))}${td('Ambiente',p.amb==='produção'?'<span class="badge ok">produção</span>':'<span class="badge info">homologação</span>')}${td('Client ID',`<span class="mono">${esc(p.cid)}</span>`)}${td('Segredo',p.st==='revogado'?'<span class="tl">revogado</span>':apxMask(p))}${td('Rotação',p.st==='revogado'?'—':`<span class="${d<0?'prazo-err':d<=15?'prazo-warn':'prazo-ok'}">${d<0?'vencido':'vence em '+d+' d'}</span>`)}${td('Limite',p.rate?p.rate+'/min':'—')}${td('Situação',apxStBadge(p))}${td('',`<button class="btn sm sec" onclick="event.stopPropagation();apxAbrir('${p.id}')">Abrir</button>`)}</tr>`}))}
function apxAbrir(id){const p=APX_P(id),d=apxDiasExp(p),rev=p.st==='revogado';
 openDrawer(esc(p.n),`${kvs([['Situação',apxStBadge(p)+' · '+(p.amb==='produção'?'produção':'homologação')],['Contrato',esc(p.contrato)],['Fluxo',p.id==='P02'?'OAuth 2.0 com PKCE; cada paciente entra com a própria conta':'OAuth 2.0 client credentials (token de 15 min)'],['Client ID',`<span class="mono">${esc(p.cid)}</span>`],['Segredo',rev?'revogado':apxMask(p)+` ${info('Só os 4 últimos caracteres aparecem. O segredo inteiro é mostrado uma única vez, na criação ou na rotação, e guardado com hash.')}`],['Última rotação',x2Dmy(p.rot)+(rev?'':` · ${d<0?'<span class="prazo-err">vencido</span>':'vence em '+d+' dias'}`)],['IPs permitidos',p.ips.length?esc(p.ips.join(', ')):'—'],['Limite',p.rate?`${p.rate} chamadas por minuto · agora ${p.uso}/min`:'—']])}
 ${p.rate?`<div class="barras" style="margin-top:8px">${barra('Uso do limite',p.uso,p.rate,Math.round(p.uso/p.rate*100)+'%')}</div>`:''}
 <h4 style="margin:12px 0 4px">Escopos do contrato</h4>${p.esc.length?`<div class="stack" style="gap:4px">${p.esc.map(k=>`<div class="tl" style="font-size:13px"><span class="mono">${k}</span> ${apxSens(k)?'<span class="x2-sec">sensível · pede consentimento</span>':''}</div>`).join('')}</div>`:'<p class="tl">Nenhum.</p>'}
 ${p.cons!=null&&p.esc.some(apxSens)?`<p class="tl" style="margin-top:6px">${p.cons} de ${p.vidas||'—'} pacientes do contrato deram consentimento para os escopos sensíveis. Sem consentimento, a chamada volta 403 e fica no log.</p>`:''}
 <h4 style="margin:12px 0 4px">Últimos acessos</h4><div class="at-list">${APX_LOG.filter(l=>l.p===id).slice(0,4).map(l=>`<div class="at-row"><div class="grow"><span class="mono">${l.m} ${esc(l.r)}</span><small>${l.h} · ${esc(l.quem)}</small></div><span class="badge ${l.s<300?'ok':l.s===429?'warn':'err'}">${l.s}</span></div>`).join('')||'<p class="tl">Nenhum.</p>'}</div>
 ${rev?'':`<div class="row" style="margin-top:14px;gap:6px"><button class="btn" onclick="apxRotacionar('${id}')">Rotacionar segredo</button><button class="btn sec" onclick="apxLimite('${id}')">Mudar limite</button><button class="btn sec" onclick="apxEscEdit('${id}')">Escopos</button><button class="btn ghost" style="color:var(--err)" onclick="apxRevogar('${id}')">Revogar</button></div>`}`)}
function apxNovoSeg(){const c='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';let s='';for(let i=0;i<4;i++)s+=c[Math.floor(Math.random()*c.length)];return s}
function apxRotacionar(id){const p=APX_P(id);x2Mot('Rotacionar segredo · '+esc(p.n),'Um segredo novo é gerado. O antigo continua valendo pelo período de troca e depois para de funcionar. O parceiro é avisado pelo contato técnico do contrato.',(m,x)=>{p.last4=apxNovoSeg();p.rot=PL_HOJE;x2Aud('API de parceiros',`Segredo de ${p.n} rotacionado; o anterior vale por ${x.grace}. Motivo: ${m}`);closeDrawer();reView();
  openModal(`${mh('Segredo novo · '+esc(p.n))}<div class="mb"><p style="font-size:14px">Copie agora e entregue pelo canal seguro do contrato. <b>Ele não será mostrado de novo</b>; aqui fica só o final.</p><p>${apxMask(p)}</p><p class="tl">O anterior vale por ${esc(x.grace)}.</p></div><div class="mf"><button class="btn sec" onclick="toast('Segredo copiado para a área de transferência (uma vez só)')">Copiar segredo (uma vez)</button><button class="btn" onclick="closeModal()">Pronto</button></div>`)},'Rotacionar','',
 `<div class="field"><label>Período de troca (o antigo ainda vale)</label><select class="in" data-x2="grace"><option>24 horas</option><option>1 hora</option><option>sem período (revoga já)</option></select></div>`)}
function apxRevogar(id){const p=APX_P(id);x2Mot('Revogar '+esc(p.n),'Todas as credenciais e tokens param na hora. Webhooks são pausados. Os logs continuam guardados.',m=>{p.st='revogado';p.rate=0;APX_WH.filter(w=>w.p===id).forEach(w=>w.st='pausado');x2Aud('API de parceiros',`${p.n} revogado: ${m}`);closeDrawer();reView();toast(p.n+' revogado')},'Revogar','danger')}
function apxLimite(id){const p=APX_P(id);x2Mot('Limite de chamadas · '+esc(p.n),'Acima do limite, a API responde 429 com o tempo de espera. O limite vem do contrato.',(m,x)=>{p.rate=+x.rate;x2Aud('API de parceiros',`Limite de ${p.n} alterado para ${x.rate}/min: ${m}`);apxAbrir(id);reView();toast('Limite atualizado')},'Salvar','',`<div class="field"><label>Chamadas por minuto</label><select class="in" data-x2="rate">${[30,60,120,300,600].map(v=>`<option ${p.rate===v?'selected':''}>${v}</option>`).join('')}</select></div>`)}
function apxEscEdit(id){const p=APX_P(id);openModal(`${mh('Escopos · '+esc(p.n))}<div class="mb"><p style="font-size:14px">Só o que está no contrato. Escopo sensível exige cláusula de LGPD no contrato, aprovação do encarregado (DPO) e o consentimento de cada paciente.</p>${APX_ESC.map(([k,n,s])=>`<label class="check" style="align-items:flex-start"><input type="checkbox" class="apxE" value="${k}" ${p.esc.includes(k)?'checked':''}><span><span class="mono">${k}</span> ${s?'<span class="x2-sec">sensível</span>':''}<small class="tl" style="display:block">${esc(n)}</small></span></label>`).join('')}
 <div class="field" style="margin-top:8px"><label for="apxEM">Motivo <span class="req">*</span></label><textarea class="in" id="apxEM" rows="2" placeholder="Ex.: aditivo 2 do contrato"></textarea></div><label class="check"><input type="checkbox" id="apxDpo">Aprovado pelo encarregado de dados (DPO) para os escopos sensíveis</label></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="apxEscOk('${id}')">Salvar escopos</button></div>`)}
function apxEscOk(id){const p=APX_P(id),l=[...document.querySelectorAll('.apxE:checked')].map(e=>e.value),m=($('#apxEM').value||'').trim(),novosSens=l.filter(k=>apxSens(k)&&!p.esc.includes(k));if(m.length<10){toast('Escreva o motivo (pelo menos 10 letras)','warn');$('#apxEM').focus();return}if(novosSens.length&&!$('#apxDpo').checked){toast('Escopo sensível novo precisa da aprovação do DPO','warn');return}p.esc=l;x2Aud('API de parceiros',`Escopos de ${p.n}: ${l.join(', ')||'nenhum'}. Motivo: ${m}`);closeModal();apxAbrir(id);reView();toast('Escopos salvos')}
function apxEscopos(){const ps=APX_PARC.filter(p=>p.st!=='revogado');return `<p class="tl" style="margin-bottom:8px">Cada chamada é conferida em três passos: a credencial vale, o escopo está no contrato e, se o dado for sensível, o paciente deu consentimento para aquele parceiro. ${info('O consentimento é dado pelo paciente na Área do paciente ou no app, por parceiro e por escopo, e pode ser retirado a qualquer momento; retirou, a próxima chamada já volta 403.')}</p>`+tabela(['Escopo',...ps.map(p=>p.n.split(' (')[0])],APX_ESC.map(([k,n,s])=>`<tr>${td('Escopo',`<span class="mono">${k}</span> ${s?'<span class="x2-sec">sensível</span>':''}<small class="tl" style="display:block">${esc(n)}</small>`)}${ps.map(p=>td(p.n.split(' (')[0],p.esc.includes(k)?`<span class="prazo-ok">✓</span>${s&&p.cons!=null?` <small class="tl">${p.cons} consentimentos</small>`:s&&p.id==='P02'?' <small class="tl">só o próprio paciente</small>':''}`:'<span class="tl">—</span>')).join('')}</tr>`))}
function apxLogs(){const l=APX_LOG.filter(x=>(!APX_LP||x.p===APX_LP)&&(!APX_LS||String(x.s)[0]===APX_LS));
 return `<div class="fbar"><select class="in" style="max-width:240px" aria-label="Parceiro" onchange="APX_LP=this.value;reView()"><option value="">Todos os parceiros</option>${APX_PARC.map(p=>`<option value="${p.id}" ${APX_LP===p.id?'selected':''}>${esc(p.n)}</option>`).join('')}</select><select class="in" style="max-width:200px" aria-label="Resultado" onchange="APX_LS=this.value;reView()"><option value="">Todos os resultados</option><option value="2" ${APX_LS==='2'?'selected':''}>Sucesso (2xx)</option><option value="4" ${APX_LS==='4'?'selected':''}>Negadas (4xx)</option></select><button class="btn sm ghost" onclick="toast('Exportação dos logs registrada na trilha (CSV, sem CPF completo)')">${I.dl} Exportar</button></div>
 ${tabela(['Quando','Parceiro','Quem','Chamada','Escopo','Resultado','IP'],l.map(x=>`<tr class="clk" onclick="apxLog(${APX_LOG.indexOf(x)})">${td('Quando',x.h)}${td('Parceiro',esc(APX_P(x.p).n))}${td('Quem',esc(x.quem))}${td('Chamada',`<span class="mono x2-wrapx">${x.m} ${esc(x.r)}</span>`)}${td('Escopo',`<span class="mono">${esc(x.e)}</span>`)}${td('Resultado',`<span class="badge ${x.s<300?'ok':x.s===429?'warn':'err'}">${x.s}</span>${x.obs?`<small class="tl" style="display:block">${esc(x.obs)}</small>`:''}`)}${td('IP',`<span class="mono">${x.ip}</span>`)}</tr>`),'Nenhuma chamada com esses filtros')}
 <p class="tl" style="margin-top:8px">Logs guardados por 5 anos, sem o CPF completo nem o conteúdo clínico da resposta. Cada exportação também vai para a trilha.</p>`}
function apxLog(i){const x=APX_LOG[i];openDrawer('Chamada '+x.h,`${kvs([['Parceiro',esc(APX_P(x.p).n)],['Quem',esc(x.quem)],['Chamada',`<span class="mono x2-wrapx">${x.m} ${esc(x.r)}</span>`],['Escopo',`<span class="mono">${esc(x.e)}</span>`],['Resultado',`${x.s} · ${esc(x.obs||'ok')}`],['IP',x.ip],['Tempo',x.ms+' ms'],['ID da requisição',`<span class="mono">req_${(i*7919+104729).toString(36)}</span>`],apxSens(x.e)?['Consentimento',x.s===200?'verificado (CONS-'+(2000+i)+')':'não encontrado']:null])}`)}
function apxWebhooks(){return `<p class="tl" style="margin-bottom:8px">Cada evento vai assinado com HMAC-SHA256 (cabeçalho X-DeoClinic-Signature) e um identificador para o parceiro descartar repetidos. Falhou, tenta de novo em 1, 4, 15 e 60 minutos; depois de 24 h sem sucesso, o webhook é pausado e o administrador avisado.</p>`+tabela(['Parceiro','Endereço','Eventos','Situação','Entregas','Última',''],APX_WH.map((w,i)=>`<tr>${td('Parceiro',esc(APX_P(w.p).n))}${td('Endereço',`<span class="mono x2-wrapx">${esc(w.url)}</span>`)}${td('Eventos',esc(w.ev.join(', ')))}${td('Situação',`<span class="badge ${w.st==='ativo'?'ok':w.st==='pausado'?'neutral':'err'}">${w.st}</span>`)}${td('Entregas',`${w.ok} ok · ${w.falha} falhas`)}${td('Última',esc(w.ult))}${td('',`<div class="row" style="gap:4px;flex-wrap:nowrap"><button class="btn sm sec" onclick="apxWhTeste(${i})">Testar</button>${w.falha?`<button class="btn sm ghost" onclick="apxWhReenviar(${i})">Reenviar falhas</button>`:''}<button class="btn sm ghost" onclick="apxWhPausa(${i})">${w.st==='pausado'?'Retomar':'Pausar'}</button></div>`)}</tr>`))}
function apxWhTeste(i){const w=APX_WH[i];toast(`Evento de teste assinado enviado para ${APX_P(w.p).n}: ${w.st==='com falhas'?'503 (o parceiro está fora; nova tentativa programada)':'200 em 210 ms'}`,w.st==='com falhas'?'warn':'ok')}
function apxWhReenviar(i){const w=APX_WH[i];x2Aud('API de parceiros',`${w.falha} eventos reenviados para ${APX_P(w.p).n}`);w.ok+=w.falha;w.falha=0;w.st='ativo';w.ult='04/11 '+hhmm(new Date())+' · 200';reView();toast('Falhas reenviadas: entregues')}
function apxWhPausa(i){const w=APX_WH[i];x2Mot((w.st==='pausado'?'Retomar':'Pausar')+' webhook',`${esc(APX_P(w.p).n)}. Pausado, os eventos ficam guardados por 7 dias e saem ao retomar.`,m=>{w.st=w.st==='pausado'?'ativo':'pausado';x2Aud('API de parceiros',`Webhook de ${APX_P(w.p).n} ${w.st==='pausado'?'pausado':'retomado'}: ${m}`);reView();toast('Webhook '+(w.st==='pausado'?'pausado':'retomado'))},'Confirmar')}
const APX_CHECK=[['auth','Autenticação OAuth client credentials e token de 15 min'],['escopo','Chamadas fora do escopo voltam 403'],['cons','Escopo sensível sem consentimento volta 403 (e com consentimento, 200)'],['rate','Limite de chamadas respeitado (429 com espera)'],['wh','Webhook recebe e valida a assinatura HMAC'],['carga','Teste de carga com dados fictícios por 24 h']];
function apxHomolog(){const hs=APX_PARC.filter(p=>p.st==='homologação');return `<div class="grid g2"><div class="card at-card"><h3>Ambientes</h3><div class="sub">Mesma API, dados separados</div>${kvs([['Produção','<span class="mono x2-wrapx">https://api.deoclinic.com.br/v1</span>'],['Homologação','<span class="mono x2-wrapx">https://api.sandbox.deoclinic.com.br/v1</span>'],['Dados da homologação','pacientes, agendas e resultados fictícios, recriados toda segunda'],['Documentação','OpenAPI 3.1 com exemplos por escopo'],['CORS','só as origens cadastradas de cada parceiro (apps web)']])}</div>
 ${hs.map(p=>{const c=p.check||{},ok=APX_CHECK.every(([k])=>c[k]);return `<div class="card at-card"><h3>${esc(p.n)} · homologação</h3><div class="sub">${esc(p.contrato)}</div>${APX_CHECK.map(([k,t])=>`<div class="x2-check ${c[k]?'ok':''}"><span class="ic">${c[k]?'✓':'·'}</span><div>${t}<small>${c[k]?'passou':'pendente'}</small></div></div>`).join('')}
 <div class="row" style="margin-top:10px;gap:6px"><button class="btn sec" onclick="apxTestes('${p.id}')">Rodar os testes automáticos</button><button class="btn" ${ok?'':'disabled aria-disabled="true"'} onclick="apxPromover('${p.id}')" ${tipAttr('Promover para produção',ok?'Gera a credencial de produção, com aprovação do DPO.':'Só com todos os testes passando.')}>Promover para produção</button></div></div>`}).join('')||'<div class="card"><p class="tl">Nenhum parceiro em homologação.</p></div>'}</div>`}
function apxTestes(id){const p=APX_P(id);APX_CHECK.forEach(([k])=>p.check[k]=true);x2Aud('API de parceiros',`Testes automáticos de ${p.n} rodados na homologação: 6 de 6 passaram`);reView();toast('6 de 6 testes passaram na homologação')}
function apxPromover(id){const p=APX_P(id);x2Mot('Promover '+esc(p.n)+' para produção','Gera uma credencial nova de produção (a da homologação continua só na homologação). Precisa da aprovação do encarregado de dados (DPO) quando há escopo sensível.',(m,x)=>{if(p.esc.some(apxSens)&&!x.dpo){toast('Há escopo sensível: marque a aprovação do DPO','warn');return}p.amb='produção';p.st='ativo';p.cid=p.cid.replace('_sbx','');p.last4=apxNovoSeg();p.rot=PL_HOJE;x2Aud('API de parceiros',`${p.n} promovido para produção: ${m}`);reView();toast(p.n+' em produção; o segredo foi entregue pelo canal seguro')},'Promover','',`<label class="check"><input type="checkbox" data-x2="dpo">Aprovado pelo encarregado de dados (DPO)</label>`)}
function apxNovo(){APX_NEW={n:'',tipo:'Empresa cliente',esc:[],rate:60};openModal(`${mh('Novo parceiro da API')}<div class="mb"><div class="formgrid"><div class="field"><label for="axN">Nome <span class="req">*</span></label><input class="in" id="axN" placeholder="Razão social ou nome do app"></div><div class="field"><label for="axT">Tipo</label><select class="in" id="axT"><option>Empresa cliente</option><option>Operadora</option><option>App</option><option>Agregador de agenda</option></select></div><div class="field"><label for="axC">Contrato <span class="req">*</span></label><input class="in" id="axC" placeholder="Número do contrato"></div><div class="field"><label for="axI">IPs permitidos</label><input class="in" id="axI" placeholder="Ex.: 177.10.22.0/24"></div></div>
 <h4 style="margin:8px 0 4px">Escopos</h4>${APX_ESC.map(([k,n,s])=>`<label class="check"><input type="checkbox" class="axE" value="${k}">${esc(n)} ${s?'<span class="x2-sec">sensível</span>':''}</label>`).join('')}
 <p class="tl" style="margin-top:8px">Começa sempre na homologação, com dados fictícios. A credencial de produção só sai depois dos testes e, com escopo sensível, da aprovação do DPO.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="apxNovoOk()">Criar na homologação</button></div>`)}
function apxNovoOk(){const n=($('#axN').value||'').trim(),c=($('#axC').value||'').trim();if(!n){toast('Informe o nome','warn');$('#axN').focus();return}if(!c){toast('Sem contrato não há credencial','warn');$('#axC').focus();return}
 const id='P0'+(APX_PARC.length+1),esc2=[...document.querySelectorAll('.axE:checked')].map(e=>e.value),ip=($('#axI').value||'').trim();APX_PARC.splice(APX_PARC.length-1,0,{id,n,tipo:$('#axT').value,contrato:c,cid:semAc(n).replace(/[^a-z]/g,'').slice(0,4)+'_sbx_'+apxNovoSeg().toLowerCase(),last4:apxNovoSeg(),criado:PL_HOJE,rot:PL_HOJE,amb:'homologação',st:'homologação',rate:30,uso:0,ips:ip?[ip]:[],esc:esc2,cons:0,check:{}});
 x2Aud('API de parceiros',`Parceiro ${n} criado na homologação (contrato ${c}; escopos: ${esc2.join(', ')||'nenhum'})`);closeModal();APX_ABA='homolog';reView();toast(n+' criado na homologação; segredo mostrado uma vez ao contato técnico')}
GUIDES['api-parceiros']=['Parceiros e credenciais: cada parceiro tem a sua credencial (client ID e segredo), só com o final do segredo à mostra. Rotacione a cada 90 dias ou quando houver suspeita.','Escopos e consentimento: o que cada contrato pode chamar. Dado sensível (resultados, atestados, avaliações) só com o consentimento do paciente.','Logs de acesso: quem chamou o quê, quando, de onde e o resultado, inclusive as negadas.','Webhooks e homologação: eventos assinados para o parceiro e um ambiente com dados fictícios para testar antes da produção.'];
REGRAS['API de parceiros']={aba:'Rede e parceiros · Clinicas §14 (API B2B) e correção urgente nº 1',itens:[['O que estava errado','A API B2B do Clinicas (b2b.php) tinha token fixo escrito no código, um bypass de autenticação por sufixo /debug e CORS liberado para qualquer origem (Access-Control-Allow-Origin: *). Atestados, avaliações e última consulta saíam por CPF, sem escopo de contrato.'],['Credencial','Uma por parceiro, OAuth 2.0 client credentials (app do paciente: PKCE com a conta do próprio paciente). Token de 15 min. Segredo guardado com hash, mostrado uma vez; na tela, só o final. Rotação a cada 90 dias, com período de troca.'],['Escopo','Por contrato. Escopo sensível exige cláusula de LGPD, aprovação do DPO e consentimento do paciente por parceiro e por escopo; sem ele, 403.'],['Limite','Chamadas por minuto por parceiro; acima, 429 com o tempo de espera. Lista de IPs por parceiro.'],['Logs','Cada chamada: quem, o quê, quando, de onde e o resultado, sem CPF completo; guardados 5 anos; exportação registrada.'],['Webhooks','Assinados (HMAC-SHA256), com identificador para descartar repetidos, novas tentativas e pausa automática.'],['Homologação','Todo parceiro começa na homologação com dados fictícios; produção só com os testes passando e aprovação.'],['Agendamento','O que entra pela API vira pedido na caixa de Pedidos de agendamento; a API não marca direto na agenda.']]};

/* Contador para a Home (cartão de módulos) */
if(typeof MOD_BADGE!=='undefined')Object.assign(MOD_BADGE,{'pedidos-agendamento':()=>pdaPendentes(),carteira:()=>CRT_ACORDOS.filter(a=>a.parc.some(p=>p.st==='vencida'||(p.st==='aberta'&&p.venc<PL_HOJE))).length,'api-parceiros':()=>APX_WH.filter(w=>w.st==='com falhas').length});
